SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (342::BIGINT, 'La clase en sí es interesante, pero en general es solo ver videos. Sin embargo no es para nada pesado el curso y con que participes de vez en cuando y hagas los trabajos que pida en clase todo bien.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'd2cd5f815f316a3439967bc91fb7d9c89e6d34e34bd1159e8e828dac9fa16a6e'::TEXT, ARRAY[663]::BIGINT[]),
    (342::BIGINT, 'El curso es muy fácil de pasar, solo se entrega 3 evaluaciones, antes de cada clase se debe ver un material que el deja y charlar sobre lo que mas le gusto del material y listo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-03T00:00:00+00:00'::TIMESTAMPTZ, '8e516fe2ba7a1d530e36253a23e4f98a9be5e37af121ef3ce8ea6860426b2136'::TEXT, ARRAY[1156]::BIGINT[]),
    (342::BIGINT, 'Muy chill. Solo se entregan 3 trabajos en todo el semestre basado en las lecturas que pone en el planeamiento y en clases se hablan de ellas (algunos temas llaman la atención, otros no tanto)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'b9d0cd59654be04c334c40710a7dd548ce398a250932e770a1ee1c9ce8afe4fe'::TEXT, ARRAY[1156]::BIGINT[]),
    (342::BIGINT, 'NO use el cel en clase. El material se lee antes de la clase,durante clase se comenta el tema y se profundiza lo que interese a los estudiantes. 3 evaluaciones durante el curso q son fáciles, al profesor le interesa que aprendamos.Se exploran temas interesantes que normalmente no se hablan en compu.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2024-08-12T00:00:00+00:00'::TIMESTAMPTZ, '925b3bd8bf91991db59311d99f79c18163665593b4ff33c458c9a2b2712f89e8'::TEXT, ARRAY[1156]::BIGINT[]),
    (342::BIGINT, 'El tema no es feo, sin embargo solo pone a ver videos de una hora y luego charla, nada didáctico o que de verdad enseñe'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-08-06T00:00:00+00:00'::TIMESTAMPTZ, '539ffb23efa31169946ad802bfcf7c8015903581b76a9082c0ce0c04c25629b1'::TEXT, ARRAY[663]::BIGINT[]),
    (342::BIGINT, 'Me encantó esta humanística. El profe explicó temas muy interesantes y que abren la mirada del mundo, con un carisma excepcional. Se nota que le gusta de lo que habla. Toda actividad fue dentro y no fuera de clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a79c2dde4cbb7d65a2aca5ad88c3be2fafb25ec5c73dba28db2a1986d31d8e48'::TEXT, ARRAY[835]::BIGINT[]),
    (342::BIGINT, 'El curso fue excelente, aprendes de temas muy variados, él deja unos materiales para revisar antes de la clase, el punto es verlos y comentar en base a eso, lo ideal es que todos participen. Las evaluaciones fueron pocas y muy sencillas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, '9c3760ad94e8898bf6378a3df45889465e6393655cf72a0b11d6404730e3c01e'::TEXT, ARRAY[1156]::BIGINT[]),
    (342::BIGINT, 'Las clases son interesantes y la evaluación fácil de lograr'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, '43d9bda9bca239e2ecce78646c7515635d598fb97dbfc08e7c76784e4a71e791'::TEXT, ARRAY[1156]::BIGINT[]),
    (342::BIGINT, 'No se embarque, si de verdad quiere aprender mejor vaya buscando otro profe.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, '1027e676f865aeadb59a6dd8e78a052dac5cb2f496d01c194f41e2aaa547ac6a'::TEXT, ARRAY[1020]::BIGINT[]),
    (342::BIGINT, 'Apresar de su buena experiencia en programación y otras áreas, no es nada bueno como profesor, explica pésimo y con la ayuda que brinda (si es que la da) uno queda en las mismas'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2019-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'a7328349c85ca81334b74add3602393f3f11324e7571b3ca63385c64ff4e2e23'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (342::BIGINT, 'Explica bien los contenidos del curso, si revisa los trabajos un poco duro y es exigente pero se debe a que se apega a aprovechar las horas extra clases del curso. Pero en general es pura vida y considera la carga que se lleva en el semestre.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '3545e2665f729ea97cf79a3693afb3aace947b43a92b16ea5558a79d821a8906'::TEXT, ARRAY[1054]::BIGINT[]),
    (342::BIGINT, 'Llegó de cambio de profesor, pero explicó los contenidos del curso muy bien. Hace la clase interesante lo que hace los trabajos fáciles.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'd2a3b0a4903ad737e6274c110466616f448ba0d082ecb65d1e1906ce0cbc8187'::TEXT, ARRAY[1156]::BIGINT[]),
    (342::BIGINT, 'Excelente profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'ddfbec16584af09f5b37c69cdad4e15fd34a76cab0691ed8d2981be6563ac12e'::TEXT, ARRAY[1156]::BIGINT[]),
    (342::BIGINT, 'Se toma las cosas muy personales, se enoja si cometes un error en un proyecto, lo cual hace que su revision no sea objetiva, regaña innecesariamente en lugar de ayudar a mejorar el proyecto. Califica con mas enfasis cosas que no tienen que ver con el proyecto en si.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Pocos exámenes']::TEXT[], '2018-06-28T00:00:00+00:00'::TIMESTAMPTZ, '2ad3743b50c865523b64a0149544343e5d2cac6eceb77e15bec0e9942fb3320a'::TEXT, ARRAY[1054]::BIGINT[]),
    (342::BIGINT, 'Da plantillas de todo lo que hay que hacer. El profe en ningún momento da materia. No jode con nada y ayuda si uno lo ocupa. Trata bien a los alumnos. Un buen profe para llevar proyecto!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '58f5c15755890c4b4cb01e185a24fe8b4ea88f1b5a15d5c2fa1837e0f25ba3b9'::TEXT, ARRAY[1165]::BIGINT[]),
    (342::BIGINT, 'Deja varios trabajos y un proyecto final, pero no es muy estricto y nos trabajos son sencillos. Se preocupa por interesar a los estudiantes en temas de la actualidad relacionados con la tecnologia en general. A pesar de que el curso no se presta, intenta hacer la clase interesante.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '50bedf2b8fe952713f8d023dc618f90fb761075b639fda8098537730728827b4'::TEXT, ARRAY[1156]::BIGINT[]),
    (342::BIGINT, 'Un curso muy interesante, él sabe mucho de los temas, la materia es complicada, pero como todos los cursos, depende del estudiante y su interés en la materia. Es muy organizado con los criterios a evaluar, pero todo lo deja para último.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Exámenes retadores', 'Aspectos de calificación claros']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '23801ebfaa475d2402a6d69b6f127c0dd6e38f856c999c5734794f907f10c9ea'::TEXT, ARRAY[1054]::BIGINT[]),
    (342::BIGINT, 'Es un buen profesor, sabe mucho y aclara muy bien las preguntas que uno tenga. Pero si hay que estudiar y poner bastante interes en los trabajos. Es sarcastico con algunas cosas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Brinda apoyo']::TEXT[], '2017-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'fb59745dd08fbaa012539ed1e96b2990a3c5151d473a8203183c13ba9589f026'::TEXT, ARRAY[1054]::BIGINT[]),
    (342::BIGINT, 'Es un profesor que sabe lo que hace pero es difícil comprender su clase, además es un profesor muy duro y hace sentir mal a los estudiantes y hace que los estudiantes pierdan el interés tanto en el curso como en la carrera'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Exámenes retadores']::TEXT[], '2017-05-04T00:00:00+00:00'::TIMESTAMPTZ, '4be2d1cd614b534467d5b324a51f65479524c0d31f819c1527d6ec0e84eaa514'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (342::BIGINT, 'Pro: Es un muy buen profesor, le interesa mucho todo lo que se refiere al tema de Ensamblador. Le gusta que el estudiante intente hacer las cosas por él mismo o por lo menos ver un poco el interés en uno. Con: Tarda demasiado en revisar y dar las notas de los trabajos.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'd0506ada82ea96124a4985e6103da4f8a611320f619038a792c3fb3d85dcb8c9'::TEXT, ARRAY[1032]::BIGINT[]),
    (342::BIGINT, 'Exelente profesor, es difícil pero se aprende muchísimo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'd05cdc2f4c33b1f7d5085b0ddbac2bb84db638d7685a316d4f9fd7e43df00070'::TEXT, ARRAY[1032]::BIGINT[]),
    (342::BIGINT, 'No sabe explicar!'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2016-06-03T00:00:00+00:00'::TIMESTAMPTZ, '73977f54da7771a55a975217e6d37265cfddafadd4d48f45529e46f6decff124'::TEXT, ARRAY[1032]::BIGINT[]),
    (342::BIGINT, 'Exc profesor, sólo poner atención en clase y cumplir con todo lo que asigna y se pasa con muy buena nota. Con arduinos si el profe ve que uno la pulsea le ayuda y da puntos extra en quices y algunas clases.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Da crédito extra']::TEXT[], '2016-02-05T00:00:00+00:00'::TIMESTAMPTZ, '13bfddfc5d6bc3ca97bfcbf8c9c0b9f5cb74ebf284d169b7fd933b979b7ff535'::TEXT, ARRAY[1032]::BIGINT[]),
    (342::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-03-30T00:00:00+00:00'::TIMESTAMPTZ, '873b55125068aebb190dce667cfc5a8531f3b8b03517738e12045b4178c44041'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (342::BIGINT, 'Excelente para explicar, los proyectos son rudos pero se aprende mucho. Usualmente llega tarde a clases.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'd131ef2e64404cd45f746c716f2c2966b47e599878f4b95c32c457e318b929da'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (342::BIGINT, 'Muy irresponsable'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '3588f8a84bb309451757abda3b5236e15310e5df75d6711725354a3af74d43b1'::TEXT, ARRAY[1032]::BIGINT[]),
    (342::BIGINT, 'Crack de profesor, es uno de los profes que da los cursos de una manera única, todo el curso es rudo pero se aprende demasiado. Siempre atento a que los estudiantes aprendan, es buena nota ayuda bastante si uno no entiende.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'b3365203965f8bc056404e6b1c5c2e45324c22016162eff15154484672445ef1'::TEXT, ARRAY[1032]::BIGINT[]),
    (342::BIGINT, 'Es muy bueno explicando y siempre esta dispuesto a ayudar a los estudiantes'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'e9913f84b512126ed71508f0e8a2f9fb4035571127264923cb3902da20b24397'::TEXT, ARRAY[1032]::BIGINT[]),
    (342::BIGINT, 'Siempre está dispuesto a aclarar dudas de todo tipo'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'eefc0169bdb72f29ff1d7d4751d89f082d81789e39601958c7fe9cc4e9540fc7'::TEXT, ARRAY[1032]::BIGINT[]),
    (342::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'f15bd9c07f84d4472d551a0c0cff20a738909aff2611babe9baa2e8c68613536'::TEXT, ARRAY[1032]::BIGINT[]),
    (342::BIGINT, 'Le apasionan temas como los de arqui y se preocupa porque el estudiante aprenda, no es fácil, ya que depende mucho del estudiante, al tener que investigar por cuenta propia muchos de los temas. Se enfoca mucho en la parte de ensamblador.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'f1735679d23fc976cea7fff6966a1a583493dc2b12b26194169bc55647605103'::TEXT, ARRAY[1032]::BIGINT[]),
    (342::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '3d50e9c471754cde8b6907cf3bcc14c24d5c8819d1d891ed8821ef815861c39d'::TEXT, ARRAY[1020, 1022]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
